import { AppInfoPayload } from "./common";
export interface IframeMessage<T = unknown> {
    type: string;
    data: T;
}
export interface PreviewReadyMessage extends IframeMessage<Record<string, never>> {
    type: 'PreviewReady';
}
export interface ConsoleMessage extends IframeMessage<Record<string, any>> {
    method: string;
    type: 'Console';
}
export interface ChildLocationChangeMessage extends IframeMessage<any> {
    type: 'ChildLocationChange';
}
export interface CreatePageMessage extends IframeMessage<string> {
    type: 'CreatePage';
}
export interface RenderErrorMessage extends IframeMessage<any> {
    type: 'RenderError';
    location?: any;
}
export interface RenderErrorRepairMessage extends IframeMessage<any> {
    type: 'RenderErrorRepair';
}
export interface PageScreenshotMessage extends IframeMessage<string> {
    type: 'PageScreenshot';
}
export interface UpdateRoutesMessage extends IframeMessage<{
    routes: any[];
}> {
    type: 'UpdateRoutes';
}
/** 热更新消息 */
export interface HmrMessage extends IframeMessage<Record<string, never>> {
    type: 'HmrMessage';
    msg: {
        type: 'hot' | 'errors';
        data?: any;
    };
}
/** devServer相关消息 */
export interface DevServerMessage extends IframeMessage<{
    type: 'devServer-status';
    status: 'connected' | 'disconnected' | 'hmr-apply-success';
}> {
    type: 'DevServerMessage';
}
/**
 * 预览态下链接点击通知父页面处理。
 * iframe 内直接跳转可能被浏览器安全策略拦截，
 * 通过 postMessage 让父页面在新标签页或外壳中打开链接。
 */
export interface OpenIframeLinkMessage extends IframeMessage<{
    href: string;
    external: boolean;
}> {
    type: 'OpenIframeLink';
}
export type OutgoingMessage = PreviewReadyMessage | HmrMessage | ConsoleMessage | ChildLocationChangeMessage | CreatePageMessage | RenderErrorMessage | RenderErrorRepairMessage | PageScreenshotMessage | DevServerMessage | UpdateRoutesMessage | OpenIframeLinkMessage;
export interface GetRoutesMessage extends IframeMessage<Record<string, never>> {
    type: 'GetRoutes';
}
export type IncomingMessage = GetRoutesMessage;
export interface ParentApi {
}
export interface ChildApi {
    getRoutes: () => Promise<any[]>;
    getSourceMap: () => Promise<string>;
    /** 更新应用信息 */
    updateAppInfo: (appInfo: AppInfoPayload) => void;
    apiProxy: {
        api_get: (url: string, config?: any) => Promise<any>;
        api_post: (url: string, data?: any, config?: any) => Promise<any>;
        api_put: (url: string, data?: any, config?: any) => Promise<any>;
        api_delete: (url: string, config?: any) => Promise<any>;
        api_patch: (url: string, data?: any, config?: any) => Promise<any>;
        api_head: (url: string, config?: any) => Promise<any>;
        api_options: (url: string, config?: any) => Promise<any>;
    };
}
